import{_ as a,o as n,c as e,ab as t}from"./chunks/framework.DCf1Sbhf.js";const m=JSON.parse('{"title":"RTSP","description":"","frontmatter":{},"headers":[],"relativePath":"front/realtime-media/RTSP实时监控.md","filePath":"front/realtime-media/RTSP实时监控.md","lastUpdated":1773017852000}'),p={name:"front/realtime-media/RTSP实时监控.md"};function r(i,s,l,o,d,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="rtsp" tabindex="-1">RTSP <a class="header-anchor" href="#rtsp" aria-label="Permalink to &quot;RTSP&quot;">​</a></h1><p><strong>全称： Real Time Streaming Protocol</strong> —— 实时流媒体协议 由 <strong>IETF 标准化</strong>，摄像头、网络录像机(NVR)、安防系统最常用的流媒体协议。</p><p>实际上 RTSP <strong>不负责传视频内容，只负责控制</strong> 真正的音视频数据是通过 <strong>RTP/RTCP</strong> 传输的。</p><blockquote><p>RTSP —— 建立连接、请求视频、控制播放 RTP —— 实际传输视频和音频数据 RTCP —— 质量控制、延时、丢包反馈</p></blockquote><p>他们之间的关系如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>             控制</span></span>
<span class="line"><span>     ┌─────────────────┐</span></span>
<span class="line"><span>     │      RTSP       │</span></span>
<span class="line"><span>     └─────────────────┘</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>     ┌─────────────────┐</span></span>
<span class="line"><span>     │ RTP（传视频数据） │</span></span>
<span class="line"><span>     └─────────────────┘</span></span>
<span class="line"><span>     ┌─────────────────┐</span></span>
<span class="line"><span>     │ RTCP（质量反馈）  │</span></span>
<span class="line"><span>     └─────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>RTSP 会提供一种格式的地址，例如：</p><div class="language-typescript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rtsp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//admin:123456@192.168.1.100:554/stream1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>注意：</strong></p><blockquote><p>绝大多数监控设备输出的实时视频，也就是rtsp，<strong>浏览器根本不支持</strong>。 因此必须经过“中间处理”，转成浏览器能接受的格式。</p></blockquote><hr><h1 id="转接-技术" tabindex="-1">转接”技术 <a class="header-anchor" href="#转接-技术" aria-label="Permalink to &quot;转接”技术&quot;">​</a></h1><p>正因为浏览器不支持 RTSP，才催生了一系列“转接”技术。当你在浏览器中访问一个现代监控系统的网页时，无非就几种方案</p><p><strong>浏览器插件（已淘汰）：</strong></p><p>过去，监控厂商会提供 ActiveX 或 NPAPI 插件，让浏览器能直接播放 RTSP。但随着 Chrome、Firefox 等现代浏览器淘汰插件，这种方式已经被淘汰了</p><p><strong>纯前端解码</strong></p><p>利用 <code>WebAssembly</code> 技术，将 H.264 解码器编译成 wasm 在浏览器中运行，然后通过 WebSocket 接收原始的 RTP/H.264 数据包进行解码。不过这种方案，<strong>技术要求高、延迟高、性能消耗大、兼容性还糟</strong> 。它要求浏览器做本不擅长的事情，并且只解决了视频解码问题，音频同步、网络适应性等问题依然棘手。这只是一种技术演示或特定场景的解决方案，无法成为行业标准。</p><p><strong>服务器端转码 / 转封装</strong></p><p>简单来说，就是在后端服务器<strong>实时地将摄像头的 RTSP 流拉取过来，然后将其转换成浏览器支持的标准格式</strong>。</p><p>一般可以通过<strong>FFmpeg</strong>拉取摄像头的 RTSP 流，然后根据需要进行转码/转封装，当然有些厂商也有自己的SDK专门来进行处理。反正最后* *浏览器支持**的格式其实也无非下面几种：</p><ul><li><strong>HTTP-FLV / WebSocket：</strong> 早期常用，依赖 Flash</li><li><strong>HLS（HTTP Live Streaming）：</strong> 苹果推出的标准，将流切割成小的 <code>.ts</code> 文件片段，通过 HTTP 下载播放，不过延迟较高</li><li><strong>MPEG-DASH：</strong> 类似 HLS 的开放标准，国外常用</li><li><strong>WebRTC</strong>：服务器将 RTSP 流转码/转封装后，通过 <strong>WebRTC 协议</strong> 发送给浏览器，WebRTC 支持 UDP、低延迟（可做到 &lt; 500ms），并且是现代浏览器原生支持的标准</li></ul><hr><h1 id="mediamtx-是什么" tabindex="-1">Mediamtx 是什么？ <a class="header-anchor" href="#mediamtx-是什么" aria-label="Permalink to &quot;Mediamtx 是什么？&quot;">​</a></h1><p>Mediamtx（原名 rtsp-simple-server）是一个 <strong>音视频协议网关 / 流媒体中间服务器</strong>。</p><p>它的工作非常简单，但非常关键：</p><table tabindex="0"><thead><tr><th>它能做的事情</th><th>作用</th></tr></thead><tbody><tr><td><strong>接收摄像头推流（RTSP / RTMP / WebRTC / HLS / SRT / UDP ...）</strong></td><td>摄像头 → Mediamtx</td></tr><tr><td><strong>把流转成多种格式再输出</strong></td><td>提供给网页、APP、NVR 等使用</td></tr><tr><td>支持<strong>转协议、转码、录像、鉴权、回放、跨网络分发</strong></td><td>让摄像头能被安全、稳定地播放</td></tr></tbody></table><p>也就是说：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">摄像头（RTSP） → Mediamtx → 用户浏览器（HLS / WebRTC）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,28)])])}const g=a(p,[["render",r]]);export{m as __pageData,g as default};
